```css
/* Define on :root to make globally available */
:root {
  /* Design tokens */
  --color-brand: #6366f1;
  --color-brand-dark: #4f46e5;
  --color-text: #1a1a2e;
  --color-text-muted: #6b7280;
  --color-bg: #ffffff;
  --color-bg-subtle: #f9fafb;
  --color-border: #e5e7eb;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px rgba(0,0,0,0.07);
  --shadow-lg: 0 10px 15px rgba(0,0,0,0.1);

  --font-sans: 'Inter', system-ui, sans-serif;
  --font-mono: 'Fira Code', 'Cascadia Code', monospace;

  --spacing-1: 0.25rem;
  --spacing-2: 0.5rem;
  --spacing-4: 1rem;
  --spacing-8: 2rem;

  --transition-fast: 150ms ease;
  --transition-normal: 250ms ease;
}

/* Dark mode override */
@media (prefers-color-scheme: dark) {
  :root {
    --color-text: #e8e8f0;
    --color-bg: #0f0f13;
    --color-bg-subtle: #1a1a24;
    --color-border: #2d2d40;
  }
}

/* Manual dark mode via class */
.dark {
  --color-text: #e8e8f0;
  --color-bg: #0f0f13;
}

/* Use variables */
.button {
  background: var(--color-brand);
  color: white;
  border-radius: var(--radius-md);
  padding: var(--spacing-2) var(--spacing-4);
  transition: background var(--transition-fast);
}

.button:hover {
  background: var(--color-brand-dark);
}

/* Variables with fallback */
color: var(--color-custom, var(--color-text));
/* If --color-custom not defined, use --color-text */
```

---

```css
/* ——— Transitions: smooth property changes ——— */
.button {
  background: var(--color-brand);
  transform: translateY(0);
  box-shadow: var(--shadow-sm);
  /* Transition specific properties */
  transition:
    background 150ms ease,
    transform 150ms ease,
    box-shadow 150ms ease;
}

.button:hover {
  background: var(--color-brand-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

/* ——— Keyframe animations ——— */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.5; }
}

@keyframes shimmer {
  from { background-position: -200% 0; }
  to   { background-position: 200% 0; }
}

/* Apply animations */
.card {
  animation: fadeIn 300ms ease forwards;
  animation-delay: 100ms;       /* Wait before starting */
  animation-fill-mode: both;    /* Apply from/to styles outside active period */
}

.spinner {
  animation: spin 800ms linear infinite;
}

.skeleton {
  background: linear-gradient(
    90deg,
    #f0f0f0 25%,
    #e0e0e0 50%,
    #f0f0f0 75%
  );
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
}

/* ——— Performance tip ——— */
/* Only animate/transition these properties — they're handled by the GPU compositor */
/* and don't trigger layout or paint: */
transform: translateX/Y/Z(), rotate(), scale(), skew()
opacity

/* These force layout recalculation on every frame — avoid for animation: */
/* width, height, top, left, margin, padding, font-size */
```

